import AppKit
import CryptoKit

/// 클립보드에서 읽어 온 내용
struct CapturedContent {
    var kind: ClipItem.Kind
    var text: String = ""
    var rtfData: Data?
    var pngData: Data?
    var filePaths: [String] = []
    var detail: String?
    var hash: String
}

enum PasteboardReader {
    /// nspasteboard.org 관례: 비밀번호·임시 데이터는 기록하지 않는다.
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    static let maxImageBytes = 30 * 1024 * 1024
    /// 이보다 긴 글(로그 파일 통째 등)은 기록하지 않는다. 기록 파일이 커지면 저장과 검색이 매번 느려진다.
    static let maxTextBytes = 1024 * 1024

    static func read(_ pb: NSPasteboard) -> CapturedContent? {
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard !types.isEmpty, types.isDisjoint(with: ignoredTypes) else { return nil }

        // 1) 파일 (Finder 복사)
        if let urls = pb.readObjects(forClasses: [NSURL.self],
                                     options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map(\.path)
            let joined = paths.joined(separator: "\n")
            return CapturedContent(kind: .file, text: joined, filePaths: paths,
                                   hash: digest("file:" + joined))
        }

        // 2) 텍스트 (서식 있는 경우 RTF도 함께 보관)
        if let string = pb.string(forType: .string),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard string.utf8.count <= maxTextBytes else { return nil }
            // 앞뒤 빈칸·줄바꿈만 다른 글은 같은 항목으로 본다.
            return CapturedContent(kind: .text, text: string, rtfData: pb.data(forType: .rtf),
                                   hash: textHash(string))
        }

        // 3) 이미지
        if let png = pngData(from: pb), png.count <= maxImageBytes {
            var detail: String?
            if let rep = NSBitmapImageRep(data: png) {
                detail = "\(rep.pixelsWide)×\(rep.pixelsHigh)"
            }
            return CapturedContent(kind: .image, pngData: png, detail: detail,
                                   hash: digest(png))
        }

        return nil
    }

    private static func pngData(from pb: NSPasteboard) -> Data? {
        if let png = pb.data(forType: .png) { return png }
        guard let tiff = pb.data(forType: .tiff),
              let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }

    static func textHash(_ string: String) -> String {
        digest("text:" + string.trimmingCharacters(in: .whitespacesAndNewlines))
    }

    private static func digest(_ string: String) -> String {
        digest(Data(string.utf8))
    }

    private static func digest(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
